insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,metadata) values ('ulisse','marsh-library','core','Marsh’s Library','St Patrick’s Close, Dublin','building',16,'2026-11-09','Approximate building reference','The existing historic library is mentioned in Stephen’s thoughts, recalling his reading.','Published approximate point for the building; architectural inventory identifies the historic library and its address.','d2cc4fae6e2a4a6d27fd7d272a857f1e2ba77c699f0333215011582203182dd8','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-09","texts":{"it":"Biblioteca storica accanto alla cattedrale di San Patrizio, fondata all’inizio del Settecento. Il punto identifica l’edificio a St Patrick’s Close.","en":"A historic library beside St Patrick’s Cathedral, founded in the early eighteenth century. The point identifies the building on St Patrick’s Close.","fr":"Bibliothèque historique près de la cathédrale Saint-Patrick, fondée au début du XVIIIe siècle. Le point désigne le bâtiment de St Patrick’s Close.","es":"Biblioteca histórica junto a la catedral de San Patricio, fundada a comienzos del siglo XVIII. El punto señala el edificio de St Patrick’s Close."}},"additionalSources":[{"url":"https://www.buildingsofireland.ie/buildings-search/building/50110023/marshs-library-st-patricks-close-dublin-8-dublin","label":"NIAH 50110023"}]}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','3:core:marsh-library',3,'marsh-library','core',3,'mentioned','Stephen recalls having read prophecies in Marsh’s Library; the phrase reports a past activity without developing a scene there.','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"explicitCategory":true}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','3:core:marsh-library:original',3,'3:core:marsh-library','original','en','original','Houses of decay, mine, his and all. You told the Clongowes gentry you had an uncle a judge and an uncle a general in the army. Come out of them, Stephen. Beauty is not there. Nor in the stagnant bay of Marsh’s library where you read the fading prophecies of Joachim Abbas.','James Joyce · Ulysses · 1922 · Chapter III','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Marsh’s library"],"reviewedAt":"2026-11-09"}'::jsonb) on conflict do nothing;
